import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BjkiRu3Q.js";const p=JSON.parse('{"title":"Ρύθμιση API AI, email και μηνυμάτων","description":"","frontmatter":{},"headers":[],"relativePath":"el/integrations/ai-messaging-setup.md","filePath":"el/integrations/ai-messaging-setup.md"}'),i={name:"el/integrations/ai-messaging-setup.md"};function c(r,e,s,_,l,n){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="ρυθμιση-api-ai-email-και-μηνυματων" tabindex="-1">Ρύθμιση API AI, email και μηνυμάτων <a class="header-anchor" href="#ρυθμιση-api-ai-email-και-μηνυματων" aria-label="Permalink to &quot;Ρύθμιση API AI, email και μηνυμάτων&quot;">​</a></h1><p>Έλεγχος πηγαίου κώδικα v0.7.26. Τα παρακάτω ονόματα υπάρχουν στον κώδικα adapters. Δεν αποτελούν πλήρη σύμβαση ενεργοποίησης ή επιβεβαίωση πραγματικής αποστολής.</p><table tabindex="0"><thead><tr><th>Υπηρεσία</th><th>Μεταβλητές διακομιστή</th></tr></thead><tbody><tr><td>Gemini</td><td><code>GEMINI_API_KEY</code></td></tr><tr><td>Resend</td><td><code>RESEND_API_KEY</code>, <code>RESEND_FROM</code> ή <code>SMTP_FROM</code></td></tr><tr><td>SendGrid</td><td><code>SENDGRID_API_KEY</code>, <code>SMTP_FROM</code></td></tr><tr><td>HTTP relay email</td><td><code>SMTP_HTTP_RELAY_URL</code>, προαιρετικά <code>SMTP_PASS</code>, <code>SMTP_HOST</code>, ρύθμιση αποστολέα</td></tr><tr><td>Twilio SMS</td><td><code>TWILIO_ACCOUNT_SID</code>, <code>TWILIO_AUTH_TOKEN</code>, <code>TWILIO_FROM_NUMBER</code> ή <code>TWILIO_PHONE_NUMBER</code></td></tr><tr><td>Αποστολή WhatsApp</td><td><code>WHATSAPP_PHONE_NUMBER_ID</code>, <code>WHATSAPP_ACCESS_TOKEN</code></td></tr><tr><td>Εισερχόμενο Meta webhook</td><td><code>META_WEBHOOK_VERIFY_TOKEN</code>, <code>META_APP_SECRET</code></td></tr></tbody></table><h2 id="ρυθμιση-και-αποδοχη" tabindex="-1">Ρύθμιση και αποδοχή <a class="header-anchor" href="#ρυθμιση-και-αποδοχη" aria-label="Permalink to &quot;Ρύθμιση και αποδοχή&quot;">​</a></h2><ol><li>Εκδώστε κλειδί AI από Google AI Studio ή εγκεκριμένο έργο Gemini. Ελέγξτε χρήση μοντέλου, ιδιωτικότητα και κόστος. Μόνο στον διακομιστή. Δοκιμάστε συνθετικές συνομιλίες και ανάληψη από χειριστή, χωρίς περιττά προσωπικά στοιχεία ή μη εξουσιοδοτημένες ενέργειες.</li><li>Για email επιλέξτε εγκεκριμένο πάροχο και επαληθεύστε αποστολέα/domain, παράδοση και αποτυχίες. Ορίστε ρητά αποστολέα. Απλό SMTP host δεν παρέχει εγγενή αποστολή SMTP σε αυτόν τον adapter· απαιτείται εγκεκριμένο HTTP relay για τη σχετική διαδρομή.</li><li>Για SMS απαιτούνται εγκεκριμένος αποστολέας και διαπιστευτήρια Twilio. Ελέγξτε συγκατάθεση, εξαίρεση και αποτυχίες. Για WhatsApp απαιτείται εγκεκριμένος λογαριασμός Meta Business, phone ID, access token και εγκεκριμένα πρότυπα όπου χρειάζονται.</li><li>Για Meta ο κώδικας διαθέτει GET επαλήθευση και υπογεγραμμένο POST στο <code>/api/v1/webhooks/messaging/:channel</code> (whatsapp, meta_messenger ή instagram). Καταχωρίστε callback μόνο μετά από έγκριση και επαλήθευση πρόσβασης. Ελέγξτε HMAC στο αρχικό σώμα αιτήματος, αντιστοίχιση λογαριασμού με εταιρεία, αποδεκτό συμβάν και προστασία διπλοεγγραφής. Μην απενεργοποιείτε υπογραφές.</li><li>Υπάρχει μόνιμο ιστορικό και επαναλήψεις, αλλά απαιτείται εξωτερική αποδοχή. Ελέγξτε εξαίρεση, μη διπλή παράδοση και σαφή αποτυχία. Ο οδηγός δεν εγκρίνει δημόσια λήψη κρατήσεων ή εξωτερική αποστολή.</li></ol><p>Οι ονομασίες του καταλόγου ενδέχεται να διαφέρουν από τις πραγματικές μεταβλητές adapters. Χρησιμοποιήστε την εγκατεστημένη έκδοση και εγκεκριμένες οδηγίες. Απαγορεύεται ανεπίσημη αυτοματοποίηση WhatsApp Web.</p>',6)])])}const P=t(i,[["render",c]]);export{p as __pageData,P as default};
